package edu.sharespace;

import edu.sharespace.Domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.http.HttpStatus;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
import java.time.*;import java.util.*;import java.util.stream.*;

record ResourceIn(@NotBlank String name,@NotBlank String description,@NotBlank String category,@NotBlank String location,@NotNull Boolean requiresTraining,String requiredTrainingDescription,@NotNull Boolean requiresApproval,@NotNull @Min(1) @Max(168) Integer maxBookingHours,String usageRules,String imageUrl){}
record BookingIn(@NotNull Long resourceId,@NotNull OffsetDateTime startTime,@NotNull OffsetDateTime endTime,@NotBlank @Size(max=1000) String purpose){}
record DecisionIn(@NotBlank @Size(max=500) String reason){}
record ConditionIn(@NotNull ReportType reportType,@NotBlank @Size(max=2000) String description,String imageUrl){}
record IncidentIn(@NotNull IncidentType type,@NotBlank @Size(max=2000) String description){}
record ResolveIn(@NotBlank @Size(max=1000) String resolutionNote){}

@Service class Workflow {
 final UserRepository users; final ResourceRepository resources; final BookingRepository bookings; final ConditionRepository conditions; final IncidentRepository incidents; final AuditRepository audit; @Value("${app.demo-mode:false}") boolean demoMode; @Value("${app.active-booking-limit:3}") int activeBookingLimit; @Value("${app.waitlist-enabled:true}") boolean waitlistEnabled;
 Workflow(UserRepository u,ResourceRepository r,BookingRepository b,ConditionRepository c,IncidentRepository i,AuditRepository a){users=u;resources=r;bookings=b;conditions=c;incidents=i;audit=a;}
 User actor(String email){if(!demoMode)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication is required; demo identity is disabled");String e=(email==null||email.isBlank())?"taylor@campus.edu":email.toLowerCase(Locale.ROOT);if(!Set.of("taylor@campus.edu","maya@campus.edu","admin@campus.edu").contains(e))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Unknown development demo identity");return users.findByEmail(e).orElseThrow(()->new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Demo data is not initialized"));}
 void accessBooking(Booking b,User u){if(u.role==Role.ADMIN||b.requester.id.equals(u.id)||b.resource.owner.id.equals(u.id))return;throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This booking belongs to another user");}
 void event(User u,String action,String type,Long id,String reason){AuditEvent e=new AuditEvent();e.actor=u;e.action=action;e.entityType=type;e.entityId=id;e.reason=reason;audit.save(e);}
 boolean conflict(Resource r,OffsetDateTime s,OffsetDateTime e,Long excluding){return bookings.findByResourceIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(r.id,List.of(BookingStatus.APPROVED,BookingStatus.CHECKED_OUT,BookingStatus.RETURN_PENDING_CONFIRMATION,BookingStatus.OVERDUE),e,s).stream().anyMatch(b->!Objects.equals(b.id,excluding));}
 @Transactional Resource create(ResourceIn in,User actor){if(actor.role!=Role.OWNER&&actor.role!=Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only resource owners can list resources");Resource r=new Resource();copy(r,in);r.owner=actor;r=resources.save(r);event(actor,"RESOURCE_CREATED","RESOURCE",r.id,"New resource listing");return r;}
 @Transactional Resource update(Long id,ResourceIn in,User actor){Resource r=resources.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found"));if(actor.role!=Role.ADMIN&&!r.owner.id.equals(actor.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the resource owner can edit this listing");copy(r,in);r=resources.save(r);event(actor,"RESOURCE_UPDATED","RESOURCE",r.id,"Updated listing");return r;}
 void copy(Resource r,ResourceIn in){r.name=in.name();r.description=in.description();r.category=in.category();r.location=in.location();r.requiresTraining=in.requiresTraining();r.requiredTrainingDescription=in.requiredTrainingDescription();r.requiresApproval=in.requiresApproval();r.maxBookingHours=in.maxBookingHours();r.usageRules=in.usageRules();r.imageUrl=in.imageUrl();}
 @Transactional Booking request(BookingIn in,User actor){User requester=users.findByIdForUpdate(actor.id).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Identity no longer exists"));Resource r=resources.findByIdForUpdate(in.resourceId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found"));if(!"AVAILABLE".equalsIgnoreCase(r.status))throw new ResponseStatusException(HttpStatus.CONFLICT,"This resource is not currently available for booking");if(!in.endTime().isAfter(in.startTime()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End time must be after start time");if(Duration.between(in.startTime(),in.endTime()).compareTo(Duration.ofHours(r.maxBookingHours))>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Booking exceeds this resource's "+r.maxBookingHours+" hour limit");if(!in.startTime().isAfter(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Start time must be in the future");boolean occupied=conflict(r,in.startTime(),in.endTime(),null);if(occupied&&!waitlistEnabled)throw new ResponseStatusException(HttpStatus.CONFLICT,"This resource is already reserved for part of that time");long active=bookings.findByRequesterIdOrderByCreatedAtDesc(requester.id).stream().filter(b->List.of(BookingStatus.PENDING,BookingStatus.APPROVED,BookingStatus.CHECKED_OUT,BookingStatus.RETURN_PENDING_CONFIRMATION).contains(b.status)).count();if(active>=activeBookingLimit)throw new ResponseStatusException(HttpStatus.CONFLICT,"Active booking limit reached ("+activeBookingLimit+")");Booking b=new Booking();b.resource=r;b.requester=requester;b.startTime=in.startTime();b.endTime=in.endTime();b.purpose=in.purpose();b.eligibilityStatus=eligible(r,requester)?"ELIGIBLE":"INELIGIBLE";boolean instant=!occupied&&!r.requiresApproval&&b.eligibilityStatus.equals("ELIGIBLE");b.status=occupied?BookingStatus.WAITLISTED:instant?BookingStatus.APPROVED:BookingStatus.PENDING;b.decisionReason=occupied?"Waitlisted in FIFO order; an owner must review when a slot opens":instant?"Automatically approved; this resource does not require owner approval":b.eligibilityStatus.equals("ELIGIBLE")?"Awaiting owner review":eligibilityReason(r,requester);b=bookings.save(b);event(requester,"BOOKING_REQUESTED","BOOKING",b.id,b.purpose);if(occupied)event(requester,"BOOKING_WAITLISTED","BOOKING",b.id,b.decisionReason);if(instant)event(requester,"BOOKING_AUTO_APPROVED","BOOKING",b.id,b.decisionReason);return b;}
 boolean eligible(Resource r,User u){return "ACTIVE".equals(u.membershipStatus)&&(!r.requiresTraining||(u.verified&&Arrays.stream(u.training.split(",")).map(String::trim).anyMatch(t->t.equalsIgnoreCase(r.requiredTrainingDescription))));}
 String eligibilityReason(Resource r,User u){if(!"ACTIVE".equals(u.membershipStatus))return "Membership must be active before approval";if(r.requiresTraining)return "Verified training required: "+r.requiredTrainingDescription;return "Not eligible";}
 @Transactional Booking decide(Long id,User actor,boolean approve,String reason){Booking b=bookings.findByIdForUpdate(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));Resource locked=resources.findByIdForUpdate(b.resource.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found"));if(actor.role!=Role.ADMIN&&(!actor.id.equals(locked.owner.id)||actor.role!=Role.OWNER))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only this resource's owner can decide the request");if(b.status!=BookingStatus.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending requests can be approved or rejected");if(approve){if(!eligible(locked,b.requester)){b.status=BookingStatus.REJECTED;b.decisionReason=eligibilityReason(locked,b.requester);b.approvedBy=actor;b=bookings.save(b);event(actor,"BOOKING_REJECTED","BOOKING",id,b.decisionReason);promoteWaitlist(locked,actor);return b;}if(conflict(locked,b.startTime,b.endTime,b.id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Another booking was approved for this time; reassign or reject this request");b.status=BookingStatus.APPROVED;}else b.status=BookingStatus.REJECTED;b.approvedBy=actor;b.decisionReason=reason;b=bookings.save(b);event(actor,approve?"BOOKING_APPROVED":"BOOKING_REJECTED", "BOOKING",id,reason);if(!approve)promoteWaitlist(locked,actor);return b;}
 @Transactional Booking transition(Long id,User actor,String action){Booking b=bookings.findByIdForUpdate(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));accessBooking(b,actor);Resource locked=resources.findByIdForUpdate(b.resource.id).orElseThrow();accessBooking(b,actor);switch(action){case "cancel"->{if(!b.requester.id.equals(actor.id)&&actor.role!=Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the requester can cancel this booking");if(!List.of(BookingStatus.PENDING,BookingStatus.APPROVED).contains(b.status))throw new ResponseStatusException(HttpStatus.CONFLICT,"This booking can no longer be cancelled");b.status=BookingStatus.CANCELLED;}case "check-in"->{if(!b.requester.id.equals(actor.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the requester can check in");if(b.status!=BookingStatus.APPROVED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only approved bookings can be checked in");if(!conditions.existsByBookingIdAndReportType(id,ReportType.BEFORE))throw new ResponseStatusException(HttpStatus.CONFLICT,"Record a BEFORE condition report before check-in");b.status=BookingStatus.CHECKED_OUT;b.checkedInAt=Instant.now();}case "return"->{if(!b.requester.id.equals(actor.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the requester can submit the return");if(b.status!=BookingStatus.CHECKED_OUT)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only checked-out bookings can be returned");if(!conditions.existsByBookingIdAndReportType(id,ReportType.AFTER))throw new ResponseStatusException(HttpStatus.CONFLICT,"Record an AFTER condition report before returning");b.status=BookingStatus.RETURN_PENDING_CONFIRMATION;b.returnedAt=Instant.now();}case "confirm-return"->{if(actor.role!=Role.ADMIN&&!actor.id.equals(locked.owner.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the owner can confirm this return");if(b.status!=BookingStatus.RETURN_PENDING_CONFIRMATION)throw new ResponseStatusException(HttpStatus.CONFLICT,"Return is not awaiting confirmation");b.status=BookingStatus.COMPLETED;}default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown action");}b=bookings.save(b);event(actor,"BOOKING_"+action.toUpperCase(Locale.ROOT).replace('-','_'),"BOOKING",id,action);if(b.status==BookingStatus.CANCELLED||b.status==BookingStatus.COMPLETED)promoteWaitlist(locked,actor);return b;}
 void promoteWaitlist(Resource r,User actor){if(!waitlistEnabled)return;for(Booking candidate:bookings.findByResourceIdAndStatusOrderByCreatedAtAscIdAsc(r.id,BookingStatus.WAITLISTED)){if(!candidate.startTime.isAfter(OffsetDateTime.now()))continue;if(!eligible(r,candidate.requester)){candidate.status=BookingStatus.REJECTED;candidate.decisionReason=eligibilityReason(r,candidate.requester);bookings.save(candidate);event(actor,"WAITLIST_INELIGIBLE","BOOKING",candidate.id,candidate.decisionReason);continue;}if(conflict(r,candidate.startTime,candidate.endTime,candidate.id))continue;boolean instant=!r.requiresApproval;candidate.status=instant?BookingStatus.APPROVED:BookingStatus.PENDING;candidate.decisionReason=instant?"Promoted from FIFO waitlist and automatically approved": "Promoted from FIFO waitlist; owner approval required";bookings.save(candidate);event(actor,instant?"WAITLIST_PROMOTED_AND_APPROVED":"WAITLIST_PROMOTED","BOOKING",candidate.id,candidate.decisionReason);break;}}
 @Transactional ConditionReport report(Long id,ConditionIn in,User actor){Booking b=bookings.findByIdForUpdate(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));accessBooking(b,actor);if(!b.requester.id.equals(actor.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the requester can submit condition reports");if(in.reportType()==ReportType.BEFORE&&b.status!=BookingStatus.APPROVED)throw new ResponseStatusException(HttpStatus.CONFLICT,"BEFORE reports are accepted after approval and before check-in");if(in.reportType()==ReportType.AFTER&&b.status!=BookingStatus.CHECKED_OUT)throw new ResponseStatusException(HttpStatus.CONFLICT,"AFTER reports are accepted while checked out");if(conditions.existsByBookingIdAndReportType(id,in.reportType()))throw new ResponseStatusException(HttpStatus.CONFLICT,"A "+in.reportType()+" condition report already exists for this booking");ConditionReport c=new ConditionReport();c.booking=b;c.reportType=in.reportType();c.description=in.description();c.imageUrl=in.imageUrl();c.reportedBy=actor;c=conditions.save(c);event(actor,"CONDITION_"+in.reportType(),"BOOKING",id,in.description());return c;}
 @Transactional Incident incident(Long id,IncidentIn in,User actor){Booking b=getBooking(id);accessBooking(b,actor);Incident i=new Incident();i.booking=b;i.type=in.type();i.description=in.description();i.reportedBy=actor;i=incidents.save(i);event(actor,"INCIDENT_REPORTED","BOOKING",id,in.description());return i;}
 @Transactional Incident resolve(Long id,ResolveIn in,User actor){if(actor.role!=Role.ADMIN&&actor.role!=Role.OWNER)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only owners or administrators can resolve incidents");Incident i=incidents.findByIdForUpdate(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Incident not found"));if(actor.role!=Role.ADMIN&&!actor.id.equals(i.booking.resource.owner.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the resource owner can resolve this incident");if(i.status!=IncidentStatus.OPEN)throw new ResponseStatusException(HttpStatus.CONFLICT,"Incident is already resolved");i.status=IncidentStatus.RESOLVED;i.resolutionNote=in.resolutionNote();i.reviewedBy=actor;i.resolvedAt=Instant.now();i=incidents.save(i);event(actor,"INCIDENT_RESOLVED","INCIDENT",id,in.resolutionNote());return i;}
 Booking getBooking(Long id){return bookings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));}
 List<Booking> visibleBookings(User u){return u.role==Role.ADMIN?bookings.findAllByOrderByCreatedAtDesc():u.role==Role.OWNER?bookings.findAllByOrderByCreatedAtDesc().stream().filter(b->b.resource.owner.id.equals(u.id)).toList():bookings.findByRequesterIdOrderByCreatedAtDesc(u.id);}
}

@RestController @RequestMapping("/api") class ApiController {
 final Workflow w;final UserRepository users;final ResourceRepository resources;final BookingRepository bookings;final ConditionRepository conditions;final IncidentRepository incidents;final AuditRepository audit;
 ApiController(Workflow w,UserRepository u,ResourceRepository r,BookingRepository b,ConditionRepository c,IncidentRepository i,AuditRepository a){this.w=w;users=u;resources=r;bookings=b;conditions=c;incidents=i;audit=a;}
 @GetMapping("/health") Map<String,Object> health(){return Map.of("status","UP","service","ShareSpace API");}
 @GetMapping("/users/me") User me(@RequestHeader(value="X-Demo-User",required=false)String email){return w.actor(email);}
 @GetMapping("/resources") List<Resource> allResources(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(required=false)String location,@RequestParam(required=false)OffsetDateTime startTime,@RequestParam(required=false)OffsetDateTime endTime){if((startTime==null)!=(endTime==null)||startTime!=null&&!endTime.isAfter(startTime))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Provide a valid startTime and endTime pair");return resources.findAll().stream().filter(r->r.status.equalsIgnoreCase("AVAILABLE")).filter(r->q==null||q.isBlank()||(r.name+" "+r.description+" "+r.category+" "+r.location).toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT))).filter(r->category==null||category.isBlank()||r.category.equalsIgnoreCase(category)).filter(r->location==null||location.isBlank()||r.location.toLowerCase(Locale.ROOT).contains(location.toLowerCase(Locale.ROOT))).filter(r->startTime==null||!w.conflict(r,startTime,endTime,null)).toList();} @GetMapping("/resources/{id}") Resource resource(@PathVariable Long id){return resources.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found"));}
 @PostMapping("/resources") @ResponseStatus(HttpStatus.CREATED) Resource create(@Valid @RequestBody ResourceIn in,@RequestHeader(value="X-Demo-User",required=false)String email){return w.create(in,w.actor(email));}
 @PutMapping("/resources/{id}") Resource update(@PathVariable Long id,@Valid @RequestBody ResourceIn in,@RequestHeader(value="X-Demo-User",required=false)String email){return w.update(id,in,w.actor(email));}
 @GetMapping("/bookings") List<Booking> allBookings(@RequestHeader(value="X-Demo-User",required=false)String email){return w.visibleBookings(w.actor(email));} @GetMapping("/bookings/{id}") Booking booking(@PathVariable Long id,@RequestHeader(value="X-Demo-User",required=false)String email){Booking b=w.getBooking(id);w.accessBooking(b,w.actor(email));return b;}
 @PostMapping("/bookings") @ResponseStatus(HttpStatus.CREATED) Booking request(@Valid @RequestBody BookingIn in,@RequestHeader(value="X-Demo-User",required=false)String email){return w.request(in,w.actor(email));}
 @PostMapping("/bookings/{id}/approve") Booking approve(@PathVariable Long id,@Valid @RequestBody DecisionIn in,@RequestHeader(value="X-Demo-User",required=false)String email){return w.decide(id,w.actor(email),true,in.reason());} @PostMapping("/bookings/{id}/reject") Booking reject(@PathVariable Long id,@Valid @RequestBody DecisionIn in,@RequestHeader(value="X-Demo-User",required=false)String email){return w.decide(id,w.actor(email),false,in.reason());}
 @PostMapping("/bookings/{id}/cancel") Booking cancel(@PathVariable Long id,@RequestHeader(value="X-Demo-User",required=false)String email){return w.transition(id,w.actor(email),"cancel");} @PostMapping("/bookings/{id}/check-in") Booking checkIn(@PathVariable Long id,@RequestHeader(value="X-Demo-User",required=false)String email){return w.transition(id,w.actor(email),"check-in");} @PostMapping("/bookings/{id}/return") Booking ret(@PathVariable Long id,@RequestHeader(value="X-Demo-User",required=false)String email){return w.transition(id,w.actor(email),"return");} @PostMapping("/bookings/{id}/confirm-return") Booking confirm(@PathVariable Long id,@RequestHeader(value="X-Demo-User",required=false)String email){return w.transition(id,w.actor(email),"confirm-return");}
 @PostMapping("/bookings/{id}/condition-reports") @ResponseStatus(HttpStatus.CREATED) ConditionReport report(@PathVariable Long id,@Valid @RequestBody ConditionIn in,@RequestHeader(value="X-Demo-User",required=false)String email){return w.report(id,in,w.actor(email));} @GetMapping("/bookings/{id}/condition-reports") List<ConditionReport> reports(@PathVariable Long id,@RequestHeader(value="X-Demo-User",required=false)String email){Booking b=w.getBooking(id);w.accessBooking(b,w.actor(email));return conditions.findByBookingIdOrderByCreatedAtAsc(id);}
 @PostMapping("/bookings/{id}/incidents") @ResponseStatus(HttpStatus.CREATED) Incident incident(@PathVariable Long id,@Valid @RequestBody IncidentIn in,@RequestHeader(value="X-Demo-User",required=false)String email){return w.incident(id,in,w.actor(email));} @GetMapping("/incidents") List<Incident> incidentList(@RequestHeader(value="X-Demo-User",required=false)String email){User u=w.actor(email);return incidents.findAllByOrderByCreatedAtDesc().stream().filter(i->u.role==Role.ADMIN||i.booking.requester.id.equals(u.id)||i.booking.resource.owner.id.equals(u.id)).toList();} @PostMapping("/incidents/{id}/resolve") Incident resolve(@PathVariable Long id,@Valid @RequestBody ResolveIn in,@RequestHeader(value="X-Demo-User",required=false)String email){return w.resolve(id,in,w.actor(email));}
 @GetMapping("/bookings/{id}/history") List<AuditEvent> history(@PathVariable Long id,@RequestHeader(value="X-Demo-User",required=false)String email){Booking b=w.getBooking(id);w.accessBooking(b,w.actor(email));return audit.findByEntityTypeAndEntityIdOrderByTimestampAsc("BOOKING",id);} @GetMapping("/audit-events") List<AuditEvent> events(@RequestHeader(value="X-Demo-User",required=false)String email){User u=w.actor(email);return audit.findAllByOrderByTimestampDesc().stream().filter(e->e.actor.id.equals(u.id)||u.role==Role.ADMIN).toList();}
}

@Component class SeedData implements CommandLineRunner {final UserRepository users;final ResourceRepository resources;@Value("${app.seed-demo-data:false}") boolean enabled;SeedData(UserRepository u,ResourceRepository r){users=u;resources=r;}@Transactional public void run(String... args){if(!enabled)return;User student=users.findByEmail("taylor@campus.edu").orElseGet(()->users.save(new User("Taylor Morgan","taylor@campus.edu",Role.USER)));if(student.training==null||student.training.isBlank()){student.training="3D Printing Basics,Lab Safety Orientation";users.save(student);}User owner=users.findByEmail("maya@campus.edu").orElseGet(()->users.save(new User("Maya Chen","maya@campus.edu",Role.OWNER)));if(owner.training==null||owner.training.isBlank()){owner.training="Lab Safety Orientation,3D Printing Basics";users.save(owner);}if(users.findByEmail("admin@campus.edu").isEmpty())users.save(new User("Campus Administrator","admin@campus.edu",Role.ADMIN));if(resources.count()==0){String[][] rows={{"Sony Alpha A7 III Camera Kit","Photography","Media Lab · Building C","Full-frame camera, lens, tripod, and batteries."},{"Prusa i3 MK4 3D Printer","Fabrication","Innovation Hub · Room 204","FDM printer with PLA filament."},{"Electronics Workbench","Electronics","Engineering Hall · Lab 3","Oscilloscope, soldering station, and bench tools."},{"Collaboration Room 2B","Study spaces","North Library · Floor 2","Meeting room for up to six people."},{"RTX Workstation","Computing","Design Studio · Room 110","High-performance workstation for rendering and simulation."}};for(int x=0;x<rows.length;x++){Resource r=new Resource();r.name=rows[x][0];r.category=rows[x][1];r.location=rows[x][2];r.description=rows[x][3];r.owner=owner;r.requiresTraining=x==1||x==2;r.requiredTrainingDescription=x==1?"3D Printing Basics":"Lab Safety Orientation";r.requiresApproval=x!=3;r.maxBookingHours=x==1?8:24;resources.save(r);}}}}
